algorithms.pseudocode:
ml[i][d] = length of the longest match at position i with distance d (all 1 <= d <= i)
best = None; stack = [(0, (1,...,1), 0)]
while stack:
  (i, R, c) = pop()
  if i == n: best = min(best, c); continue
  push (i+1, R, c+9)                                   # literal
  for j < k with R[j] <= i: for L = REPMIN .. ml[i][R[j]]: push (i+L, move_to_front(R, j), c + 3 + j + gamma(L))
  for d = 1 .. i: for L = 2 .. ml[i][d]: push (i+L, (d) + R[0..k-2], c + 2 + gamma(L-1) + gamma(d))
return best

best[0] = {(1,...,1): 0}
for i = 0 .. n-1:
  groups = {}
  for (R, c) in best[i]:
    offer best[i+1][R] <- c + 9                                               # literal
    for j < k with R[j] <= i: for L = REPMIN .. ml[i][R[j]]: offer best[i+L][move_to_front(R, j)] <- c + 3 + j + gamma(L)
    groups[R[0..k-2]] = min(groups[R[0..k-2]], c)
  for (P, c) in groups: for d with ml[i][d] >= 2: for L = 2 .. ml[i][d]: offer best[i+L][(d) + P] <- c + 2 + gamma(L-1) + gamma(d)
return min over R of best[n][R]
